// Some portions generated by Codex

// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	openQueryPage,
	repositoryPageUrl,
	serverBaseUrl,
	setQueryEditor,
	uniqueRepositoryId
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-query-sharing');

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

async function installClipboardRecorder(page) {
	const writes = [];
	await page.exposeFunction('__recordQueryShareClipboard', (value) => {
		writes.push(value);
	});
	await page.addInitScript(() => {
		Object.defineProperty(navigator, 'clipboard', {
			configurable: true,
			value: { writeText: (value) => window.__recordQueryShareClipboard(value) }
		});
	});
	return writes;
}

function recordQueryPosts(page) {
	const posts = [];
	page.on('request', (request) => {
		if (request.method() === 'POST'
			&& new URL(request.url()).pathname.endsWith(`/repositories/${REPOSITORY_ID}/query`)) {
			posts.push(request.postData());
		}
	});
	return posts;
}

test('the Share link round-trips query text and drops stale saved-query parameters', async ({ page }) => {
	const writes = await installClipboardRecorder(page);
	const posts = recordQueryPosts(page);
	await openQueryPage(page, REPOSITORY_ID);
	const query = ' \nPREFIX ex: <https://example.org/ns#>\n'
		+ 'SELECT ?s WHERE { ?s ex:label "Håvard + café & 100% = ? #" }\n ';
	await setQueryEditor(page, query);
	await page.evaluate(() => {
		history.replaceState(history.state, '', location.pathname + '?query=old&ref=id&action=exec#other=old');
	});
	const editor = page.locator('#query-page .yasqe').first();
	const share = editor.getByRole('button', { name: 'Share query', exact: true });
	await share.focus();
	await page.keyboard.press('Enter');
	const field = editor.getByRole('textbox', { name: 'Query share link', exact: true });
	await expect(field).toBeFocused();
	const shared = await field.inputValue();
	const url = new URL(shared);
	expect(url.search).toBe('');
	expect(url.origin + url.pathname).toBe(repositoryPageUrl(REPOSITORY_ID, 'query'));
	expect(Array.from(new URLSearchParams(url.hash.slice(1)))).toEqual([['query', query]]);
	await editor.getByRole('button', { name: 'Copy link', exact: true }).click();
	await expect.poll(() => writes).toEqual([shared]);
	await page.keyboard.press('Escape');
	await expect(editor.locator('.yasqe_sharePopup')).toHaveCount(0);
	await expect(share).toBeFocused();
	await page.goto(shared, { waitUntil: 'domcontentloaded' });
	await expect.poll(() => page.locator('#query-page .CodeMirror').first()
		.evaluate((element) => element.CodeMirror.getValue())).toBe(query);
	expect(posts).toEqual([]);
});

test('Copy cURL uses the RDF4J server endpoint and copies without executing the query', async ({ page }) => {
	const writes = await installClipboardRecorder(page);
	const posts = recordQueryPosts(page);
	const errors = [];
	page.on('pageerror', (error) => errors.push(error.message));
	await openQueryPage(page, REPOSITORY_ID);
	const query = 'SELECT * WHERE { ?s ?p ?o } LIMIT 5';
	await setQueryEditor(page, query);
	await page.locator('#query-options-toggle').click();
	await page.locator('#infer').uncheck();
	await page.locator('#query-timeout').fill('37');
	await page.locator('#query-options-toggle').click();
	const expectedEndpoint = await page.locator('#query-page').evaluate((element) => {
		const configured = new URL(element.getAttribute('data-query-server-url'));
		const isLoopback = (hostname) => {
			const normalized = hostname.toLowerCase().replace(/\.$/, '');
			return normalized === 'localhost' || normalized === '[::1]' || /^127\./.test(normalized);
		};
		const origin = isLoopback(configured.hostname) && !isLoopback(location.hostname)
			? location.origin : configured.origin;
		return origin + configured.pathname.replace(/\/+$/, '') + '/repositories/'
			+ encodeURIComponent(element.getAttribute('data-query-repository-id'));
	});
	const editor = page.locator('#query-page .yasqe').first();
	await editor.getByRole('button', { name: 'Share query', exact: true }).click();
	const copyCurl = editor.getByRole('button', { name: 'Copy cURL', exact: true });
	await expect(copyCurl).toHaveAttribute('type', 'button');
	await copyCurl.click();
	await expect.poll(() => writes.length).toBe(1);
	const command = writes[0];
	expect(command).toContain(`'${expectedEndpoint}'`);
	expect(command).toContain("--data-urlencode 'query=" + query + "'");
	expect(command).toContain("--data-urlencode 'infer=false'");
	expect(command).toContain("--data-urlencode 'timeout=37'");
	expect(command).not.toContain('query-timeout=');
	expect(command).not.toContain('action=exec');
	await expect(editor.getByRole('textbox', { name: 'cURL command', exact: true })).toHaveValue(command);
	expect(posts).toEqual([]);
	expect(errors).toEqual([]);
});

test('sharing the compare editor loads its text into the primary editor only', async ({ page }) => {
	await openQueryPage(page, REPOSITORY_ID);
	await setQueryEditor(page, 'ASK { ?primary ?p ?o }');
	await page.locator('#explain-trigger').click();
	await expect(page.locator('#compare-toggle')).toBeVisible();
	await page.locator('#compare-toggle').click();
	const query = 'SELECT ("comparison + & #" AS ?value) WHERE {}';
	await setQueryEditor(page, query, 1);
	const comparison = page.locator('#query-compare-pane .yasqe');
	await comparison.getByRole('button', { name: 'Share query', exact: true }).click();
	const shared = await comparison.getByRole('textbox', { name: 'Query share link', exact: true }).inputValue();
	expect(new URLSearchParams(new URL(shared).hash.slice(1)).get('query')).toBe(query);
	await page.keyboard.press('Escape');
	await page.evaluate((href) => { location.hash = new URL(href).hash; }, shared);
	await expect.poll(() => page.locator('#query-page .CodeMirror')
		.evaluateAll((editors) => editors.map((element) => element.CodeMirror.getValue()))).toEqual([query, query]);
	await setQueryEditor(page, 'ASK { ?retainedComparison ?p ?o }', 1);
	const next = 'ASK { ?nextShared ?p ?o }';
	await page.evaluate((text) => { location.hash = new URLSearchParams({ query: text }).toString(); }, next);
	await expect.poll(() => page.locator('#query-page .CodeMirror')
		.evaluateAll((editors) => editors.map((element) => element.CodeMirror.getValue())))
		.toEqual([next, 'ASK { ?retainedComparison ?p ?o }']);
});
